SOURCE tests/procedures/support/fixture.sql;
CALL bank_lab.sp_expect_ok(DATABASE(),'update NULL fields unchanged','CALL {db}.sp_update_customer(@p3_c1,NULL,NULL,NULL,NULL,NULL,NULL)');
CALL bank_lab.sp_expect_ok(DATABASE(),'update attributes','CALL {db}.sp_update_customer(@p3_c1,''Updated Synthetic'',''Updated synthetic address'',NULL,NULL,''Verified'',NULL)');
SET @p3_ok=(SELECT full_name='Updated Synthetic' AND address='Updated synthetic address' AND kyc_status='Verified' AND is_active=1 FROM Customers WHERE customer_id=@p3_c1);
CALL bank_lab.sp_assert_true(DATABASE(),'update stored attributes',@p3_ok,'Expected procedure contract');
CALL bank_lab.sp_expect_error(DATABASE(),'update missing customer','CALL {db}.sp_update_customer(-1,NULL,NULL,NULL,NULL,NULL,NULL)',5007);
CALL bank_lab.sp_expect_error(DATABASE(),'update invalid name','CALL {db}.sp_update_customer(@p3_c1,'''',NULL,NULL,NULL,NULL,NULL)',5018);
CALL bank_lab.sp_expect_error(DATABASE(),'update invalid address','CALL {db}.sp_update_customer(@p3_c1,NULL,'''',NULL,NULL,NULL,NULL)',5018);
CALL bank_lab.sp_expect_error(DATABASE(),'update invalid email','CALL {db}.sp_update_customer(@p3_c1,NULL,NULL,''bad'',NULL,NULL,NULL)',5018);
CALL bank_lab.sp_expect_error(DATABASE(),'update invalid phone','CALL {db}.sp_update_customer(@p3_c1,NULL,NULL,NULL,''abc'',NULL,NULL)',5018);
CALL bank_lab.sp_expect_error(DATABASE(),'update invalid kyc','CALL {db}.sp_update_customer(@p3_c1,NULL,NULL,NULL,NULL,''Other'',NULL)',5018);
CALL bank_lab.sp_expect_error(DATABASE(),'update invalid active flag','CALL {db}.sp_update_customer(@p3_c1,NULL,NULL,NULL,NULL,NULL,2)',5018);
CALL bank_lab.sp_expect_error(DATABASE(),'update cannot deactivate active account owner','CALL {db}.sp_update_customer(@p3_c1,NULL,NULL,NULL,NULL,NULL,0)',5011);
SET @p3_duplicate_phone=(SELECT phone FROM Customers WHERE customer_id=@p3_c2);
CALL bank_lab.sp_expect_error(DATABASE(),'update duplicate identity sanitized','CALL {db}.sp_update_customer(@p3_c1,NULL,NULL,NULL,@p3_duplicate_phone,NULL,NULL)',5018);
CALL sp_close_account(@p3_b,NULL,1);
CALL bank_lab.sp_expect_ok(DATABASE(),'update deactivate after closure','CALL {db}.sp_update_customer(@p3_c2,NULL,NULL,NULL,NULL,NULL,0)');
CALL bank_lab.sp_expect_ok(DATABASE(),'update reactivate','CALL {db}.sp_update_customer(@p3_c2,NULL,NULL,NULL,NULL,NULL,1)');
SET @p3_ok=(SELECT is_active=1 FROM Customers WHERE customer_id=@p3_c2);
CALL bank_lab.sp_assert_true(DATABASE(),'update reactivated',@p3_ok,'Expected procedure contract');
INSERT INTO DB_User_Map(db_login,actor_type,customer_id) VALUES(USER(),'Customer',@p3_c2);
CALL bank_lab.sp_expect_error(DATABASE(),'update other customer forbidden','CALL {db}.sp_update_customer(@p3_c1,NULL,NULL,NULL,NULL,''Rejected'',NULL)',5010);
DELETE FROM DB_User_Map WHERE db_login=USER();
